{{pins}}
void setup() {
  pinMode(BUZZER_PIN, OUTPUT);
}

void loop() {
  int light = analogRead(LDR_PIN);
  if (light < ANALOG_MAX / 10) {
    noTone(BUZZER_PIN);  // very dark: silence
  } else {
    int pitch = map(light, 0, ANALOG_MAX, 200, 2000);
    tone(BUZZER_PIN, pitch);
  }
  delay(20);
}
